import React from 'react';
import {Original,Svg} from './Artwork';
export default function Planet({planet:p,index}){const x=p.x-p.rx-3,y=p.y-p.ry-3,w=p.rx*2+6,h=p.ry*2+6;return <div className="object planet" data-planet={index} style={{left:x,top:y,width:w,height:h}}><Svg viewBox={`${x} ${y} ${w} ${h}`}><defs><clipPath id={`planet-${p.id}`}><ellipse cx={p.x} cy={p.y} rx={p.rx} ry={p.ry}/></clipPath></defs><Original clipPath={`url(#planet-${p.id})`}/></Svg></div>;}
export function Sun(){return <><div className="sun-glow"/><div className="object sun" style={{left:893,top:207,width:220,height:220}}><Svg viewBox="893 207 220 220"><defs><radialGradient id="sun-paper-halo" gradientUnits="userSpaceOnUse" cx="1003" cy="317" r="106"><stop offset="0.62" stopColor="white"/><stop offset="0.79" stopColor="white" stopOpacity="0.8"/><stop offset="1" stopColor="white" stopOpacity="0"/></radialGradient><mask id="sun-clip" maskUnits="userSpaceOnUse" x="893" y="207" width="220" height="220"><circle cx="1003" cy="317" r="106" fill="url(#sun-paper-halo)"/></mask></defs><Original mask="url(#sun-clip)"/></Svg></div></>;}
